import z3

# 27 golfers, 6 weeks, 9 groups of 3
n_golfers = 27
n_weeks = 6
n_groups = 9
group_size = 3

# Decision variable: w*27 + p -> group (0..8)
# We'll create variables
W = [[z3.Int(f'w_{w}_{p}') for p in range(n_golfers)] for w in range(n_weeks)]

solver = z3.Solver()

# Each variable in 0..8
for w in range(n_weeks):
    for p in range(n_golfers):
        solver.add(W[w][p] >= 0, W[w][p] < n_groups)

# Each week, each group has exactly 3 golfers
for w in range(n_weeks):
    for g in range(n_groups):
        # count number of golfers in group g
        # Use cardinality constraint: sum of indicators = 3
        solver.add(z3.Sum([z3.If(W[w][p] == g, 1, 0) for p in range(n_golfers)]) == group_size)

# Pair constraints: no pair appears together in more than one week
# For each pair (a,b), for each week w1 < w2, ensure not both same group in both weeks
for a in range(n_golfers):
    for b in range(a+1, n_golfers):
        for w1 in range(n_weeks):
            for w2 in range(w1+1, n_weeks):
                # Not (W[w1][a] == W[w1][b] and W[w2][a] == W[w2][b])
                solver.add(z3.Not(z3.And(W[w1][a] == W[w1][b], W[w2][a] == W[w2][b])))

print("Solving...")
result = solver.check()
print(result)
if result == z3.sat:
    model = solver.model()
    sol = []
    for w in range(n_weeks):
        for p in range(n_golfers):
            sol.append(model[W[w][p]].as_long())
    print(sol)
else:
    print("UNSAT")
